# KMC 14.24.1 — same-primary moon-transfer bootstrap and regression
$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$projectFile = Join-Path $root 'KMC.Engine\KMC.Engine.csproj'
$testFile = Join-Path $root 'Tools\NavigationTests\Program.cs'
$source = Join-Path $root 'KMC.Engine\Navigation\MoonTransferBootstrap.cs'
if (-not (Test-Path $projectFile) -or -not (Test-Path $testFile)) { throw 'Run from the KMC repository root.' }
if (Test-Path $source) { throw 'MoonTransferBootstrap.cs already exists; refusing to overwrite.' }
$project = [IO.File]::ReadAllText($projectFile)
$tests = [IO.File]::ReadAllText($testFile)
$projectAnchor = '<Compile Include="Navigation\LambertTransferSearch.cs" />'
$testAnchor = 'Run("Lambert canonical short/long zero-revolution arcs", LambertCanonical);'
$methodAnchor = '    private static void SchematicAngleSelectionRegression()'
if (-not $project.Contains($projectAnchor) -or -not $tests.Contains($testAnchor) -or -not $tests.Contains($methodAnchor)) {
    throw '14.24.1 expected source anchors missing; verify frozen baseline before applying.'
}
$backup = Join-Path $env:TEMP 'KMC_14_24_1'
[IO.Directory]::CreateDirectory($backup) | Out-Null
$stamp = [DateTime]::UtcNow.ToString('yyyyMMddHHmmss')
Copy-Item $projectFile (Join-Path $backup ('Engine.' + $stamp + '.csproj.bak'))
Copy-Item $testFile (Join-Path $backup ('NavigationTests.' + $stamp + '.cs.bak'))
$sourceBytes = [Convert]::FromBase64String('')
$testMethod = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
try {
    [IO.File]::WriteAllBytes($source, $sourceBytes)
    $newProject = $project.Replace($projectAnchor,
        $projectAnchor + [Environment]::NewLine + '    <Compile Include="Navigation\MoonTransferBootstrap.cs" />')
    [IO.File]::WriteAllText($projectFile, $newProject)
    $newTests = $tests.Replace($testAnchor,
        $testAnchor + [Environment]::NewLine + '        Run("same-primary moon Lambert injection bootstrap", MoonTransferFoundationRegression);')
    $newTests = $newTests.Replace($methodAnchor, $testMethod + $methodAnchor)
    [IO.File]::WriteAllText($testFile, $newTests)
} catch {
    if (Test-Path $source) { Remove-Item $source -Force }
    [IO.File]::WriteAllText($projectFile, $project)
    [IO.File]::WriteAllText($testFile, $tests)
    throw
}
Write-Host 'KMC 14.24.1 moon-transfer foundation applied.'
Write-Host 'Build KMC.Engine / KMC.MissionControl and run NavigationTests.'
Write-Host 'NO KSP DLL REPLACEMENT REQUIRED — Engine and tests only.'
Write-Host 'Moon transfers are not wired into MAP or KSP node creation yet.'
